void main() {
  IntegrationTestWidgetsFlutterBinding.ensureInitialized();
  testWidgets(
    'actual native document percentage geometry matches Chromium fixtures',
    (tester) async {
      final gateway = Gateway();
      final theme = await PircTheme.load();
      final server = await HttpServer.bind(InternetAddress.loopbackIPv4, 0);
      final origin = 'http://127.0.0.1:${server.port}';
      final token = 'pirc_dev_${List.filled(43, 'A').join()}';
      String page = '';
      final receipts = <String>[];
      final failures = <String>[];
      final accepted = <Json>[];
      final listener = server.listen((request) async {
        try {
          await request.drain<void>();
          if (request.headers.value('authorization') != 'Bearer $token') {
            failures.add('Missing synthetic bearer');
          }
          receipts.add(request.uri.path);
          if (request.uri.path == '/api/sessions') {
            request.response.headers.contentType = ContentType.json;
            request.response.write('{"sessions":[]}');
          } else if (request.uri.path == '/page') {
            request.response.headers.contentType = ContentType(
              'text',
              'html',
              charset: 'utf-8',
            );
            request.response.write(page);
          } else {
            failures.add('Unexpected path ${request.uri}');
            request.response.statusCode = 404;
          }
          await request.response.close();
        } catch (error) {
          failures.add('$error');
        }
      });

      try {
        await gateway.call('pair', {
          'link': Uri(
            scheme: 'pirc',
            host: 'pair',
            queryParameters: {'url': origin, 'token': token},
          ).toString(),
        });

        tester.view.devicePixelRatio = 1;
        for (final raw in oracle) {
          final item = obj(raw);
          final width = (item['viewportWidth'] as num).toDouble();
          final height = (item['viewportHeight'] as num).toDouble();
          final brightness = item['theme'] == 'dark'
              ? Brightness.dark
              : Brightness.light;
          final targets = (item['targets'] as List).cast<String>();
          tester.view.physicalSize = Size(width, height);

          final extra =
              '<pre id="percent-probe" style="position:fixed;left:0;top:0">WAIT</pre>'
              '<script>${r'''window.readPercentages=function(){return Object.fromEntries(TARGETS.map(function(id){var e=document.getElementById(id);return [id,{rect:e.getBoundingClientRect().toJSON(),clientRects:Array.from(e.getClientRects()).map(function(r){return r.toJSON()}),offsetWidth:e.offsetWidth,offsetHeight:e.offsetHeight,clientWidth:e.clientWidth,clientHeight:e.clientHeight,clientLeft:e.clientLeft,clientTop:e.clientTop}]}))};document.addEventListener('DOMContentLoaded',function(){var result={boxes:window.readPercentages(),root:[document.documentElement.clientWidth,document.documentElement.clientHeight],scroll:[window.scrollX,window.scrollY]};document.getElementById('percent-probe').textContent=JSON.stringify(result)});'''.replaceAll('TARGETS', jsonEncode(targets))}</script>';
          page = (item['authoredHTML'] as String).replaceFirst(
            '</body>',
            '$extra</body>',
          );

          final windows = NativeDocumentWindows(gateway);
          final window = windows.target('', null, sourceUrl: '$origin/page');
          NativeFetchedDocument? document;
          try {
            expect(
              await window.load(
                NativeHtmlFormRequest(
                  url: '$origin/page',
                  method: 'GET',
                  target: '',
                ),
                baseUrl: origin,
              ),
              NativeDocumentLoadResult.committed,
            );
            windows.select(window);
            document = window.currentDocument!;
            await tester.pumpWidget(
              MaterialApp(
                theme: theme.build(brightness),
                home: Scaffold(
                  body: NativeDocumentScope(
                    documentUrl: '$origin/page',
                    windows: windows,
                    window: window,
                    child: NativeFetchedDocumentView(
                      document: document,
                      gateway: gateway,
                      onLink: (_) {},
                      onSubmit: (_) {},
                    ),
                  ),
                ),
              ),
            );

            Json? observed;
            for (var turn = 0; turn < 200; turn++) {
              await tester.pump(const Duration(milliseconds: 50));
              final text = html
                  .parse(document.scripts?.content?.text ?? '')
                  .getElementById('percent-probe')
                  ?.text;
              if (text != null &&
                  text.startsWith('{') &&
                  document.scripts?.ready == true) {
                observed = obj(jsonDecode(text));
                break;
              }
            }
            final label = '${item['name']} ${width.toInt()} ${item['theme']}';
            expect(
              observed,
              isNotNull,
              reason: '$label: ${document.scripts?.diagnostics}',
            );
            final browserExpected = obj(item['expected']);
            final actualBoxes = obj(observed!['boxes']);
            expect(actualBoxes.keys.toSet(), targets.toSet(), reason: label);
            for (final id in targets) {
              final actual = obj(actualBoxes[id]);
              final expected = obj(browserExpected[id]);
              final rect = obj(expected['rect']);
              final actualRect = obj(actual['rect']);
              for (final key in ['x', 'y', 'width', 'height']) {
                if (key == 'y' &&
                    id == 'parent' &&
                    const {
                      'percentage_edges_content_box',
                      'percentage_edges_border_box',
                    }.contains(item['name'])) {
                  expect(rect[key], 15);
                  expect(actualRect[key], 0);
                  continue;
                }
                expect(
                  actualRect[key],
                  closeTo((rect[key] as num).toDouble(), .3),
                  reason: '$label #$id $key vs Chromium',
                );
              }
              for (final key in [
                'offsetWidth',
                'offsetHeight',
                'clientWidth',
                'clientHeight',
                'clientLeft',
                'clientTop',
              ]) {
                expect(
                  actual[key],
                  expected[key],
                  reason: '$label #$id $key vs Chromium',
                );
              }
              expect(
                (actual['clientRects'] as List).length,
                (expected['clientRects'] as List).length,
                reason: '$label #$id client fragments',
              );
            }
            expect(observed['root'], [width, height], reason: '$label root');
            expect(observed['scroll'], [0, 0], reason: '$label initial scroll');
            expect(
              tester.takeException(),
              isNull,
              reason: '$label Flutter error',
            );
            accepted.add({
              'case': item['name'],
              'width': width,
              'theme': item['theme'],
              'status':
                  const {
                    'percentage_edges_content_box',
                    'percentage_edges_border_box',
                  }.contains(item['name'])
                  ? 'known-parent-margin-collapse-coordinate-difference'
                  : 'matches-tested-browser-geometry',
              'observed': observed,
            });
          } finally {
            await tester.pumpWidget(const SizedBox());
            windows.dispose();
            if (document?.scripts case final scripts?) await scripts.closed;
          }
        }

        tester.view.physicalSize = const Size(390, 1000);
        final scrollWindows = NativeDocumentWindows(gateway);
        final scrollWindow = scrollWindows.target(
          '',
          null,
          sourceUrl: '$origin/page',
        );
        NativeFetchedDocument? scrollDocument;
        try {
          page = r'''<!doctype html><html><head><meta charset="utf-8"><style>
html,body{margin:0;padding:0}#scroll-top{height:260px}#scroll-marker{height:40px}#scroll-tail{height:1800px}
pre{height:20px;margin:0;white-space:pre}
</style></head><body><div id="scroll-top"></div><div id="scroll-marker"></div><div id="scroll-tail"></div>
<pre id="scroll-feedback">WAIT</pre><pre id="scroll-probe">WAIT</pre><script>
var stage=0,mid=0,events=[];
document.addEventListener('scroll',function(event){
  events.push({y:window.scrollY,targetDocument:event.target===document,trusted:event.isTrusted});
  if(stage===0 && window.scrollY===200){
    mid=window.scrollY;stage=1;window.scrollTo(0,99999);
  }else if(stage===1 && window.scrollY>mid){
    stage=2;
    var end=window.scrollY,extent=document.documentElement.scrollHeight;
    var feedback='native-scroll:'+end;
    document.getElementById('scroll-feedback').textContent=feedback;
    document.getElementById('scroll-probe').textContent=JSON.stringify({mid:mid,end:end,feedback:feedback,extent:extent,events:events});
