          expect(
            await scrollWindow.load(
              NativeHtmlFormRequest(
                url: '$origin/page',
                method: 'GET',
                target: '',
              ),
              baseUrl: origin,
            ),
            NativeDocumentLoadResult.committed,
          );
          scrollWindows.select(scrollWindow);
          scrollDocument = scrollWindow.currentDocument!;
          await tester.pumpWidget(
            MaterialApp(
              theme: theme.build(Brightness.light),
              home: Scaffold(
                body: NativeDocumentScope(
                  documentUrl: '$origin/page',
                  windows: scrollWindows,
                  window: scrollWindow,
                  child: NativeFetchedDocumentView(
                    document: scrollDocument,
                    gateway: gateway,
                    onLink: (_) {},
                    onSubmit: (_) {},
                  ),
                ),
              ),
            ),
          );

          Json? scrollProbe;
          for (var turn = 0; turn < 200; turn++) {
            await tester.pump(const Duration(milliseconds: 50));
            final text = html
                .parse(scrollDocument.scripts?.content?.text ?? '')
                .getElementById('scroll-probe')
                ?.text;
            if (text != null &&
                text.startsWith('{') &&
                scrollDocument.scripts?.ready == true) {
              scrollProbe = obj(jsonDecode(text));
              break;
            }
          }
          expect(
            scrollProbe,
            isNotNull,
            reason:
                'native window scroll feedback: '
                '${scrollDocument.scripts?.diagnostics}',
          );
          expect(scrollProbe!['mid'], 200);
          expect(scrollProbe['extent'], 2140);
          expect(scrollProbe['events'], [
            {'y': 200, 'targetDocument': true, 'trusted': true},
            {'y': 1140, 'targetDocument': true, 'trusted': true},
          ]);
          expect(scrollProbe['end'], greaterThan(200));
          expect(
            scrollProbe['feedback'],
            'native-scroll:${scrollProbe['end']}',
          );
          expect(scrollDocument.scroll.hasClients, isTrue);
          expect(
            scrollDocument.scroll.offset,
            closeTo(scrollDocument.scroll.position.maxScrollExtent, .5),
            reason: 'window.scrollTo clamps to the native document end extent',
          );
          expect(
            scrollProbe['end'],
            closeTo(scrollDocument.scroll.offset, .5),
            reason: 'window.scrollY reflects native scroll feedback',
          );
          expect(tester.takeException(), isNull);
          accepted.add({
            'case': 'window_scroll_to_by_and_end_clamp',
            'status': 'native-scroll-feedback-matches-controller',
            'observed': {
              'mid': scrollProbe['mid'],
              'end': scrollProbe['end'],
              'feedback': scrollProbe['feedback'],
              'maxScrollExtent': scrollDocument.scroll.position.maxScrollExtent,
            },
          });
        } finally {
          await tester.pumpWidget(const SizedBox());
          scrollWindows.dispose();
          if (scrollDocument?.scripts case final scripts?) await scripts.closed;
        }

        expect(failures, isEmpty);
        expect(
          accepted.where(
            (item) => item['status'] == 'matches-tested-browser-geometry',
          ),
          hasLength(40),
        );
        expect(
          accepted.where(
            (item) =>
                item['status'] ==
                'known-parent-margin-collapse-coordinate-difference',
          ),
          hasLength(8),
        );
        debugPrintSynchronously(
          'PIRC_PERCENTAGES_ACCEPTANCE ${jsonEncode({'browserVersion': '153.0.8010.12', 'cases': accepted, 'httpReceipts': receipts, 'failures': failures})}',
        );
      } finally {
        tester.view.reset();
        await listener.cancel();
        await server.close(force: true);
      }
    },
  );
